input.command:
cat > candidate.mjs <<'EOF'
let source = "";
for await (const chunk of process.stdin) source += chunk;
const input = JSON.parse(source || "{}");

const { documentId, title, timestamp, idempotencyKey } = input;
const vendorStatus = input.vendorStatus ?? 200;
const json = { "content-type": "application/json" };

function observe(o) {
  console.log(JSON.stringify({
    http: o.http,
    database: o.database ?? { rows: [], transaction: { committed: false, rolledBack: o.rolledBack ?? false } },
    messages: o.messages ?? [],
    outbound: o.outbound ?? [],
    ordering: o.ordering ?? [],
    failures: o.failures ?? [],
    retryability: o.retryability ?? false
  }));
}

const body = { id: documentId, title, createdAt: timestamp };

// Idempotent replay: a prior record for the same key returns the original result without side effects.
const prior = input.replay === true ? (input.existing ?? body)
  : (idempotencyKey && input.idempotency?.[idempotencyKey]) || null;
if (prior) {
  const same = prior.title === undefined || prior.title === title;
  if (!same) {
    observe({ http: { status: 409, headers: json, body: { error: "idempotency_conflict" } },
      failures: [{ type: "idempotency_conflict", key: idempotencyKey }] });
  } else {
    observe({
      http: { status: 200, headers: { ...json, "idempotent-replay": "true" }, body: { ...body, ...prior } },
      database: { rows: [], transaction: { committed: false, rolledBack: false } },
      ordering: ["replay"]
    });
  }
} else if (typeof title !== "string" || title.trim() === "") {
  observe({ http: { status: 400, headers: json, body: { error: "validation_failed", field: "title" } },
    failures: [{ type: "validation", field: "title" }] });
} else {
  const authorize = { target: "vendor", action: "authorize", documentId, timestamp, idempotencyKey };
  const index = { target: "vendor", action: "index", documentId, title, timestamp, idempotencyKey };
  if (vendorStatus >= 400) {
    // Vendor failure on authorize: nothing indexed, persisted or emitted.
    const retryable = vendorStatus === 429 || vendorStatus >= 500;
    observe({
      http: { status: retryable ? 503 : 502, headers: json, body: { error: retryable ? "vendor_unavailable" : "vendor_rejected" } },
      outbound: [{ ...authorize, status: vendorStatus }],
      ordering: ["vendor.authorize"],
      failures: [{ type: "vendor", status: vendorStatus, retryable }],
      retryability: retryable,
      rolledBack: true
    });
  } else {
    observe({
      http: { status: 201, headers: json, body },
      database: { rows: [{ id: documentId, title, createdAt: timestamp, idempotencyKey }], transaction: { committed: true } },
      messages: [{ type: "document.created", documentId, title, timestamp, idempotencyKey }],
      outbound: [{ ...authorize, status: vendorStatus }, { ...index, status: vendorStatus }],
      ordering: ["vendor.authorize", "vendor.index", "database.commit", "message.document.created"]
    });
  }
}
EOF
npm test 2>&1 | tail -8

